  "O checkout dos links exige um gateway de pagamento conectado. Neste projeto local os links ficam registrados com produto e preço.": "El checkout de los enlaces requiere una pasarela de pago conectada. En este proyecto local, los enlaces quedan registrados con producto y precio.",
  "O cliente desta subconta também pode fazer esta conexão direto em": "El cliente de esta subcuenta también puede hacer esta conexión directamente en",
