  "O código impresso aponta para o graao, que redireciona. Trocar o destino aqui não exige reimprimir.": "El código impreso apunta al graao, que redirige. Cambiar el destino aquí no requiere volver a imprimir.",
  "O contato é criado (ou encontrado) pelo e-mail ou telefone. Peça pelo menos um dos dois.": "El contacto se crea (o se encuentra) por el correo o el teléfono. Pida al menos uno de los dos.",
