  "Nenhum lançamento ainda.": "Ningún movimiento todavía.",
  "Esta subconta não tem carteira de créditos. Quando a agência revender IA, e-mails ou WhatsApp para esta conta, o saldo, os preços e o extrato aparecem aqui.": "Esta subcuenta no tiene billetera de créditos. Cuando la agencia revenda IA, correos o WhatsApp a esta cuenta, el saldo, los precios y el extracto aparecen aquí.",
  "Os créditos acabaram: os recursos de IA estão pausados até a recarga. E-mails e WhatsApp continuam e o saldo fica negativo.": "Los créditos se acabaron: las funciones de IA están en pausa hasta la recarga. Correos y WhatsApp siguen y el saldo queda negativo.",
  "Pagamento gerado. Conclua no AbacatePay; o crédito entra quando for confirmado.": "Pago generado. Complétalo en AbacatePay; el crédito entra cuando se confirme.",
  "Os créditos desta subconta acabaram. Recarregue a carteira em Configurações → Carteira para voltar a usar a IA.": "Los créditos de esta subcuenta se acabaron. Recarga la billetera en Configuración → Billetera para volver a usar la IA.",
  "A recarga por Pix ainda não foi ativada pela agência. Fale com ela para lançar os créditos.": "La agencia aún no activó la recarga por Pix. Habla con ella para registrar los créditos.",
  "Esta subconta não tem carteira de créditos ativa.": "Esta subcuenta no tiene una billetera de créditos activa.",
  "Telefonia e Voice AI entram quando o provedor de telefonia for decidido (decisão D1). Com saldo zerado, a IA da subconta para; e-mails e WhatsApp continuam e o saldo fica negativo.": "Telefonía y Voice AI entran cuando se decida el proveedor de telefonía (decisión D1). Con saldo en cero, la IA de la subcuenta se detiene; correos y WhatsApp siguen y el saldo queda negativo.",
  "Informe quanto a agência paga por unidade e o markup (1× repassa sem margem; até 10×). O uso das subcontas com revenda ligada é descontado da carteira delas pelo preço final.": "Indica cuánto paga la agencia por unidad y el markup (1× traslada sin margen; hasta 10×). El uso de las subcuentas con reventa activada se descuenta de su billetera al precio final.",
  "Os clientes podem recarregar por Pix ou cartão em Configurações → Carteira; o valor cai na conta AbacatePay da agência.": "Los clientes pueden recargar con Pix o tarjeta en Configuración → Billetera; el monto llega a la cuenta AbacatePay de la agencia.",
  "Conecte o AbacatePay da agência para os clientes recarregarem por Pix. Até lá, lance os créditos aqui.": "Conecta el AbacatePay de la agencia para que los clientes recarguen por Pix. Mientras tanto, registra los créditos aquí.",
