  "Números de telefone da subconta, pela Twilio. As ligações aparecem em Conversas e em Relatórios → Ligações e disparam o gatilho Ligação terminou.": "Números de teléfono de la subcuenta, por Twilio. Las llamadas aparecen en Conversaciones y en Informes → Llamadas y disparan el disparador Llamada terminada.",
