  "Quando um membro confirma presença ou paga o ingresso de um evento da comunidade. Use {{trigger.title}} para o nome do evento.": "Cuando un miembro confirma asistencia o paga la entrada de un evento de la comunidad. Use {{trigger.title}} para el nombre del evento.",
