  "Quando um contato chega de um anúncio (Google Ads, Meta Ads ou outra mídia paga), por um formulário, site, loja ou webinar. Use {{trigger.campaign}} e {{trigger.source}}.": "Cuando un contacto llega desde un anuncio (Google Ads, Meta Ads u otro medio pago), por un formulario, sitio, tienda o webinar. Use {{trigger.campaign}} y {{trigger.source}}.",
