  "Abre um ticket de atendimento para o contato. Use {{action.<etapa>.number}} para o número.": "Abre un ticket de atención para el contacto. Use {{action.<etapa>.number}} para el número.",
  "Emite um certificado de um modelo para o contato, com página pública e código de verificação. Use {{action.<etapa>.code}} para o código.": "Emite un certificado de una plantilla para el contacto, con página pública y código de verificación. Use {{action.<etapa>.code}} para el código.",
