  "Coloca o contato numa sequência ativa (uma vez enquanto estiver nela).": "Pone al contacto en una secuencia activa (una vez mientras esté en ella).",
  "Soma ou subtrai pontos da pontuação do contato (use negativo para tirar).": "Suma o resta puntos de la puntuación del contacto (use un número negativo para restar).",
